// Installs a macOS LaunchAgent so CallTrack starts automatically when this
// computer logs in, restarts if it crashes (but not on a clean exit), and keeps
// the Mac awake while running (caffeinate -s).
//
//   npm run install-autostart            # port 3000, data in <checkout>/data
//   PORT=3010 npm run install-autostart  # different port
//
// Companion scripts: `npm run uninstall-autostart`, `npm run doctor`.
// The plist itself is generated by scripts/lib/launchagent.js (unit-tested).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { buildPlist, buildMarker, isTccProtectedPath, launchctlArgs, LABEL } from './lib/launchagent.js';

if (process.platform !== 'darwin') {
  console.error('install-autostart is macOS-only (it writes a LaunchAgent plist).');
  console.error('On Windows, run CallTrack as a host from the desktop app ("Start CallTrack automatically')
  console.error('when this computer turns on" in Setup), or use Task Scheduler / NSSM to run');
  console.error('`node server/index.js` at logon — see docs/TROUBLESHOOTING.md.');
  process.exit(1);
}

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const home = os.homedir();
const nodeBin = process.execPath;
const agentsDir = path.join(home, 'Library', 'LaunchAgents');
const plistPath = path.join(agentsDir, `${LABEL}.plist`);
// Logs must live OUTSIDE Desktop/Documents: macOS privacy protection stops
// launchd from opening files there (service fails to spawn with EX_CONFIG).
const logDir = path.join(home, 'Library', 'Logs', 'CallTrack');
const markerDir = path.join(home, 'Library', 'Application Support', 'CallTrack');
const markerPath = path.join(markerDir, 'service.json');
const port = Number(process.env.PORT) || 3000;
const dataDir = process.env.CRM_DATA_DIR ? path.resolve(process.env.CRM_DATA_DIR) : undefined;
const backupDir = process.env.CRM_BACKUP_DIR ? path.resolve(process.env.CRM_BACKUP_DIR) : undefined;

if (isTccProtectedPath(root, home) && !process.env.CALLTRACK_IGNORE_TCC) {
  console.warn('');
  console.warn(`WARNING: this checkout lives under ${path.relative(home, root).split(path.sep)[0]}/ — macOS privacy`);
  console.warn('protection (TCC) can block a background service from reading/writing files there,');
  console.warn('which shows up as EPERM on data/ or a service that never starts.');
  console.warn(`Recommended: move the checkout to ${path.join(home, 'CallTrack')} and re-run, or grant`);
  console.warn('System Settings → Privacy & Security → Files and Folders for node.');
  console.warn('(Set CALLTRACK_IGNORE_TCC=1 to silence this warning.)');
  console.warn('');
}

const plist = buildPlist({ nodeBin, root, logDir, port, dataDir, backupDir });
const marker = buildMarker({ plistPath, root, nodeBin, dataDir, backupDir, logDir, port });
const lc = launchctlArgs({ uid: os.userInfo().uid, plistPath });

fs.mkdirSync(agentsDir, { recursive: true });
fs.mkdirSync(logDir, { recursive: true });
fs.mkdirSync(markerDir, { recursive: true });

// Modern launchctl: bootout the old definition (ignore "not loaded"), write
// the new plist, bootstrap it into the per-user GUI domain.
try { execFileSync('launchctl', lc.bootout, { stdio: 'ignore' }); } catch { /* not loaded */ }
fs.writeFileSync(plistPath, plist);
fs.writeFileSync(markerPath, JSON.stringify(marker, null, 2));
// launchd sometimes answers "Bootstrap failed: 5: Input/output error" when a
// label is re-bootstrapped within a second of its bootout (seen live on
// 2026-09-05 — the service stayed down until a second attempt). Retry with a
// short backoff before giving up, so a reinstall never leaves the office
// server stopped.
let bootstrapped = false;
let lastErr = null;
for (let attempt = 1; attempt <= 6 && !bootstrapped; attempt += 1) {
  try {
    execFileSync('launchctl', lc.bootstrap, { stdio: attempt === 6 ? 'inherit' : 'pipe' });
    bootstrapped = true;
  } catch (err) {
    lastErr = err;
    const waitMs = 500 * attempt;
    console.warn(`launchctl bootstrap attempt ${attempt} failed (${(err.stderr || err.message || '').toString().trim().split('\n')[0]}); retrying in ${waitMs} ms…`);
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, waitMs);
  }
}
if (!bootstrapped) {
  console.error(`launchctl bootstrap failed (${lastErr && lastErr.message}). The plist is at ${plistPath};`);
  console.error(`try: launchctl ${lc.bootstrap.join(' ')}`);
  process.exit(1);
}

console.log('CallTrack autostart installed!');
console.log('  - Starts automatically when you log in to this Mac');
console.log('  - Restarts automatically if it crashes (not after a clean stop)');
console.log('  - Keeps the Mac awake while running');
console.log(`  - Port: ${port}   Data: ${marker.dataDir}`);
console.log(`  - Logs: ${path.join(logDir, 'calltrack.log')}`);
console.log(`  - Marker for the desktop app: ${markerPath}`);
console.log('');
console.log('Check it:   npm run doctor');
console.log('Remove it:  npm run uninstall-autostart');
console.log('');
console.log('IMPORTANT for reliability (one-time setup):');
console.log('  1. System Settings → Users & Groups → turn ON automatic login for this user');
console.log('  2. Give this Mac a fixed IP on your WiFi router (DHCP reservation) — see README');
console.log(`  3. Do not delete ${nodeBin} (nvm uninstall) — the service is pinned to it; re-run this script after a Node upgrade.`);
